export default {
  async fetch(request, env) {
    const url = new URL(request.url);

    // Handle API routes
    if (url.pathname === '/api/guestbook') {
      if (request.method === 'GET') {
        // Read all messages
        const messages = await env.GUESTBOOK.get('messages', 'json') || [];
        return new Response(JSON.stringify({ messages }), {
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
          },
        });
      }

      if (request.method === 'POST') {
        // Add new message
        const body = await request.json();
        const name = String(body.name || '').slice(0, 50);
        const message = String(body.message || '').slice(0, 500);

        if (!name || !message) {
          return new Response(JSON.stringify({ error: 'Name and message are required' }), {
            status: 400,
            headers: {
              'Content-Type': 'application/json',
              'Access-Control-Allow-Origin': '*',
            },
          });
        }

        const messages = await env.GUESTBOOK.get('messages', 'json') || [];
        messages.push({
          name,
          message,
          timestamp: new Date().toISOString(),
        });

        await env.GUESTBOOK.put('messages', JSON.stringify(messages));

        return new Response(JSON.stringify({ ok: true }), {
          headers: {
            'Content-Type': 'application/json',
            'Access-Control-Allow-Origin': '*',
          },
        });
      }

      return new Response('Method not allowed', { status: 405 });
    }

    // Serve the HTML page
    return new Response(`<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Farewell Ronald</title>
  <style>
    * { margin: 0; padding: 0; box-sizing: border-box; }

    body {
      font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;
      background: #000;
      color: #f5f5f7;
      -webkit-font-smoothing: antialiased;
      overflow-x: hidden;
    }

    /* Hero Section */
    .hero {
      position: relative;
      height: 100vh;
      min-height: 600px;
      overflow: hidden;
      display: flex;
      align-items: flex-end;
      justify-content: center;
    }

    .hero img {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      z-index: 1;
    }

    .hero::after {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      background: linear-gradient(to bottom, rgba(0,0,0,0.1) 0%, rgba(0,0,0,0.6) 100%);
      z-index: 2;
    }

    .hero-content {
      position: relative;
      z-index: 3;
      text-align: center;
      padding: 0 20px 80px;
      animation: fadeInUp 1s ease-out;
    }

    .hero-eyebrow {
      font-size: clamp(14px, 2vw, 17px);
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: #aeaeaf;
      margin-bottom: 8px;
    }

    .hero-title {
      font-size: clamp(48px, 10vw, 96px);
      font-weight: 700;
      letter-spacing: -0.015em;
      line-height: 1.05;
      background: linear-gradient(135deg, #f5f5f7 0%, #86868b 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 16px;
    }

    .hero-subtitle {
      font-size: clamp(21px, 4vw, 28px);
      font-weight: 400;
      color: #aeaeaf;
      line-height: 1.4;
    }

    /* Message Section */
    .message-section {
      padding: 120px 20px;
      max-width: 980px;
      margin: 0 auto;
      text-align: center;
    }

    .message-section p {
      font-size: clamp(21px, 3.5vw, 28px);
      line-height: 1.5;
      font-weight: 400;
      color: #86868b;
      margin-bottom: 24px;
    }

    .message-section p:last-child {
      margin-bottom: 0;
    }

    /* Highlight text */
    .highlight {
      background: linear-gradient(90deg, #2997ff, #30d158);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      font-weight: 600;
    }

    /* Gallery Section */
    .gallery-section {
      padding: 0 20px 120px;
      max-width: 1200px;
      margin: 0 auto;
    }

    .gallery-section .section-eyebrow {
      font-size: clamp(14px, 2vw, 17px);
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: #aeaeaf;
      text-align: center;
      margin-bottom: 40px;
    }

    .gallery-image {
      width: 100%;
      max-height: 700px;
      object-fit: cover;
      border-radius: 28px;
    }

    /* Guestbook Section */
    .guestbook-section {
      padding: 120px 20px;
      max-width: 720px;
      margin: 0 auto;
      text-align: center;
    }

    .guestbook-section .section-eyebrow {
      font-size: clamp(14px, 2vw, 17px);
      font-weight: 600;
      letter-spacing: 0.04em;
      text-transform: uppercase;
      color: #aeaeaf;
      margin-bottom: 8px;
    }

    .guestbook-section h2 {
      font-size: clamp(40px, 8vw, 64px);
      font-weight: 700;
      letter-spacing: -0.015em;
      background: linear-gradient(135deg, #f5f5f7 0%, #2997ff 50%, #30d158 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 12px;
    }

    .guestbook-section .section-desc {
      font-size: 17px;
      color: #86868b;
      margin-bottom: 48px;
    }

    /* Guestbook Form */
    .guestbook-form {
      background: #1d1d1f;
      border-radius: 20px;
      padding: 40px 32px;
      margin-bottom: 48px;
      text-align: left;
    }

    .form-group {
      margin-bottom: 20px;
    }

    .form-group label {
      display: block;
      font-size: 14px;
      font-weight: 600;
      color: #aeaeaf;
      margin-bottom: 8px;
      letter-spacing: 0.02em;
    }

    .form-group input,
    .form-group textarea {
      width: 100%;
      padding: 14px 16px;
      font-size: 17px;
      font-family: inherit;
      background: #2c2c2e;
      border: 1px solid #424245;
      border-radius: 12px;
      color: #f5f5f7;
      outline: none;
      transition: border-color 0.2s;
    }

    .form-group input:focus,
    .form-group textarea:focus {
      border-color: #2997ff;
    }

    .form-group textarea {
      min-height: 120px;
      resize: vertical;
    }

    .form-group input::placeholder,
    .form-group textarea::placeholder {
      color: #6e6e73;
    }

    .submit-btn {
      width: 100%;
      padding: 16px;
      font-size: 17px;
      font-weight: 600;
      font-family: inherit;
      background: linear-gradient(135deg, #2997ff, #30d158);
      border: none;
      border-radius: 12px;
      color: #000;
      cursor: pointer;
      transition: opacity 0.2s, transform 0.1s;
    }

    .submit-btn:hover {
      opacity: 0.9;
    }

    .submit-btn:active {
      transform: scale(0.98);
    }

    .submit-btn:disabled {
      opacity: 0.5;
      cursor: not-allowed;
    }

    /* Guestbook Messages */
    .guestbook-messages {
      text-align: left;
    }

    .guestbook-count {
      font-size: 14px;
      color: #6e6e73;
      margin-bottom: 24px;
      text-align: center;
    }

    .guestbook-entry {
      background: #1d1d1f;
      border-radius: 16px;
      padding: 24px;
      margin-bottom: 16px;
      animation: fadeInUp 0.5s ease-out;
    }

    .guestbook-entry-header {
      display: flex;
      align-items: center;
      gap: 12px;
      margin-bottom: 12px;
    }

    .guestbook-avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: linear-gradient(135deg, #2997ff, #30d158);
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 17px;
      font-weight: 600;
      color: #000;
      flex-shrink: 0;
    }

    .guestbook-name {
      font-size: 17px;
      font-weight: 600;
      color: #f5f5f7;
    }

    .guestbook-date {
      font-size: 12px;
      color: #6e6e73;
    }

    .guestbook-message {
      font-size: 15px;
      line-height: 1.5;
      color: #86868b;
    }

    .empty-state {
      text-align: center;
      padding: 48px 20px;
      color: #6e6e73;
      font-size: 15px;
    }

    .toast {
      position: fixed;
      bottom: 30px;
      left: 50%;
      transform: translateX(-50%) translateY(100px);
      background: #2c2c2e;
      color: #f5f5f7;
      padding: 14px 24px;
      border-radius: 12px;
      font-size: 15px;
      font-weight: 500;
      z-index: 100;
      transition: transform 0.3s ease;
      box-shadow: 0 8px 32px rgba(0,0,0,0.4);
    }

    .toast.show {
      transform: translateX(-50%) translateY(0);
    }

    /* Wishes Section */
    .wishes-section {
      padding: 120px 20px;
      text-align: center;
      background: linear-gradient(180deg, #000 0%, #1d1d1f 50%, #000 100%);
    }

    .wishes-section h2 {
      font-size: clamp(40px, 8vw, 64px);
      font-weight: 700;
      letter-spacing: -0.015em;
      background: linear-gradient(135deg, #f5f5f7 0%, #2997ff 50%, #30d158 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 20px;
    }

    .wishes-section p {
      font-size: clamp(17px, 2.5vw, 21px);
      color: #86868b;
      max-width: 600px;
      margin: 0 auto;
      line-height: 1.5;
    }

    /* Footer */
    .footer {
      padding: 40px 20px;
      text-align: center;
      border-top: 1px solid #424245;
    }

    .footer p {
      font-size: 12px;
      color: #6e6e73;
      margin-bottom: 4px;
    }

    /* Animations */
    @keyframes fadeInUp {
      from {
        opacity: 0;
        transform: translateY(30px);
      }
      to {
        opacity: 1;
        transform: translateY(0);
      }
    }

    .fade-in {
      opacity: 0;
      transform: translateY(30px);
      transition: opacity 0.8s ease-out, transform 0.8s ease-out;
    }

    .fade-in.visible {
      opacity: 1;
      transform: translateY(0);
    }

    /* Scroll indicator */
    .scroll-indicator {
      position: absolute;
      bottom: 30px;
      left: 50%;
      transform: translateX(-50%);
      z-index: 3;
      animation: bounce 2s infinite;
    }

    .scroll-indicator svg {
      width: 24px;
      height: 24px;
      fill: #aeaeaf;
    }

    @keyframes bounce {
      0%, 20%, 50%, 80%, 100% { transform: translateX(-50%) translateY(0); }
      40% { transform: translateX(-50%) translateY(-10px); }
      60% { transform: translateX(-50%) translateY(-5px); }
    }

    /* Loading spinner */
    .spinner {
      display: inline-block;
      width: 18px;
      height: 18px;
      border: 2px solid rgba(0,0,0,0.3);
      border-top-color: #000;
      border-radius: 50%;
      animation: spin 0.6s linear infinite;
      vertical-align: middle;
      margin-right: 8px;
    }

    @keyframes spin {
      to { transform: rotate(360deg); }
    }
  </style>
</head>
<body>
  <!-- Hero -->
  <div class="hero">
    <img src="data:image/jpeg;base64,"">
  </div>
  <div class="hero-content">
    <p class="hero-eyebrow">A tribute to our CIO</p>
    <h1 class="hero-title">Farewell, Ronald.</h1>
    <p class="hero-subtitle">Thank you for your extraordinary leadership.</p>
  </div>
  <div class="scroll-indicator">
    <svg viewBox="0 0 24 24"><path d="M12 16l-6-6h12z"/></svg>
  </div>
</div>

  <!-- Message -->
  <div class="message-section">
    <div class="fade-in">
      <p>As you embark on this <span class="highlight">new chapter</span>, we want to express our deepest gratitude for everything you've done as our CIO.</p>
      <p>Your vision, expertise, and commitment have <span class="highlight">shaped our organization</span> in countless ways.</p>
      <p>Wishing you <span class="highlight">success, happiness</span>, and exciting adventures ahead.</p>
    </div>
  </div>

  <!-- Gallery -->
  <div class="gallery-section">
    <p class="section-eyebrow fade-in">Moments to remember</p>
    <img class="gallery-image fade-in" src="data:image/jpeg;base64,">
  </div>

  <!-- Guestbook -->
  <div class="guestbook-section">
    <div class="fade-in">
      <p class="section-eyebrow">Leave your mark</p>
      <h2>Guestbook.</h2>
      <p class="section-desc">Share your favorite memories and well wishes for Ronald.</p>
    </div>

    <div class="guestbook-form fade-in" id="guestbookForm">
      <div class="form-group">
        <label for="gbName">Your Name</label>
        <input type="text" id="gbName" placeholder="Enter your name" maxlength="50" required>
      </div>
      <div class="form-group">
        <label for="gbMessage">Your Message</label>
        <textarea id="gbMessage" placeholder="Write a farewell message..." maxlength="500" required></textarea>
      </div>
      <button type="button" class="submit-btn" id="gbSubmit">Sign Guestbook</button>
    </div>

    <div class="guestbook-count fade-in" id="guestbookCount"></div>
    <div class="guestbook-messages fade-in" id="guestbookMessages">
      <div class="empty-state">Loading messages...</div>
    </div>
  </div>

  <!-- Wishes -->
  <div class="wishes-section">
    <div class="fade-in">
      <h2>Best Wishes.</h2>
      <p>From all of us who had the privilege of working with you.</p>
    </div>
  </div>

  <!-- Footer -->
  <div class="footer">
    <p>Made with love by your colleagues</p>
    <p>June 2026</p>
  </div>

  <!-- Toast notification -->
  <div class="toast" id="toast"></div>

  <script>
    // Intersection Observer for fade-in animations
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
        }
      });
    }, { threshold: 0.1 });

    document.querySelectorAll('.fade-in').forEach(el => observer.observe(el));

    // Guestbook functionality
    const submitBtn = document.getElementById('gbSubmit');
    const nameInput = document.getElementById('gbName');
    const messageInput = document.getElementById('gbMessage');
    const messagesContainer = document.getElementById('guestbookMessages');
    const countEl = document.getElementById('guestbookCount');
    const toastEl = document.getElementById('toast');

    // Get initials for avatar
    function getInitials(name) {
      return name.split(' ').map(w => w[0]).join('').toUpperCase().slice(0, 2);
    }

    // Format date
    function formatDate(isoString) {
      const d = new Date(isoString);
      return d.toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });
    }

    // Show toast
    function showToast(msg) {
      toastEl.textContent = msg;
      toastEl.classList.add('show');
      setTimeout(() => toastEl.classList.remove('show'), 3000);
    }

    // Escape HTML
    function escapeHtml(str) {
      const div = document.createElement('div');
      div.textContent = str;
      return div.innerHTML;
    }

    // Load messages
    async function loadMessages() {
      try {
        const res = await fetch('/api/guestbook');
        if (!res.ok) throw new Error('Failed to load');
        const data = await res.json();
        const messages = data.messages || [];

        countEl.textContent = messages.length === 1
          ? '1 message'
          : messages.length + ' messages';

        if (messages.length === 0) {
          messagesContainer.innerHTML = '<div class="empty-state">Be the first to leave a message!</div>';
          return;
        }

        messagesContainer.innerHTML = messages.map(function(m) {
          var name = escapeHtml(m.name);
          var msg = escapeHtml(m.message);
          var initials = getInitials(m.name);
          var date = formatDate(m.timestamp);
          return '<div class="guestbook-entry">' +
            '<div class="guestbook-entry-header">' +
            '<div class="guestbook-avatar">' + initials + '</div>' +
            '<div>' +
            '<div class="guestbook-name">' + name + '</div>' +
            '<div class="guestbook-date">' + date + '</div>' +
            '</div>' +
            '</div>' +
            '<div class="guestbook-message">' + msg + '</div>' +
            '</div>';
        }).join('');
      } catch (e) {
        messagesContainer.innerHTML = '<div class="empty-state">Unable to load messages.</div>';
        console.error(e);
      }
    }

    // Submit message
    submitBtn.addEventListener('click', async () => {
      const name = nameInput.value.trim();
      const message = messageInput.value.trim();

      if (!name || !message) {
        showToast('Please fill in all fields.');
        return;
      }

      submitBtn.disabled = true;
      submitBtn.innerHTML = '<span class="spinner"></span>Saving...';

      try {
        const res = await fetch('/api/guestbook', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name, message })
        });

        if (!res.ok) throw new Error('Failed to save');

        nameInput.value = '';
        messageInput.value = '';
        showToast('Thank you for signing the guestbook!');
        loadMessages();
      } catch (e) {
        showToast('Something went wrong. Please try again.');
        console.error(e);
      } finally {
        submitBtn.disabled = false;
        submitBtn.textContent = 'Sign Guestbook';
      }
    });

    // Load messages on page load
    loadMessages();
  </script>
</body>
</html>`, {
      headers: { 'Content-Type': 'text/html; charset=utf-8' },
    });
  }
};
